import{_ as o,o as a,c as t,a2 as l}from"./chunks/framework.CiKk3sJz.js";const f=JSON.parse('{"title":"漫画 · 第 3 话 Flexbox：一根轴的声明式布局","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.03-flexbox.md","filePath":"comics/css/EP.03-flexbox.md","lastUpdated":1792579602000}'),c={name:"comics/css/EP.03-flexbox.md"};function d(i,e,r,s,n,x){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="漫画-·-第-3-话-flexbox-一根轴的声明式布局" tabindex="-1">漫画 · 第 3 话 Flexbox：一根轴的声明式布局 <a class="header-anchor" href="#漫画-·-第-3-话-flexbox-一根轴的声明式布局" aria-label="Permalink to &quot;漫画 · 第 3 话 Flexbox：一根轴的声明式布局&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/03-flexbox">docs/css/03-flexbox.md</a> ｜ 原画：<a href="./EP.03-flexbox.svg">EP.03-flexbox.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。工具栏里的长标题把按钮挤出容器，<code>flex: 1</code> 看起来&quot;失灵&quot;了。</li><li><strong>标签君</strong>：HTML5 结构师，在场帮忙看骨架，确认问题出在弹性分配而不是结构。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>长标题压不下去、按钮被挤出容器——这不是 bug，是 flex item 的自动最小尺寸在起作用。像素酱补上 <code>min-width: 0</code> 这张&quot;救命符&quot;，又顺手分清了 <code>flex: 1</code> 与 <code>flex: auto</code> 这对孪生兄弟。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p><code>.title</code> 明明写了 <code>flex: 1; overflow: hidden;</code>，却压不到内容以下。原因：<strong>flex item 的 <code>min-width</code> 初始值不是 0，而是 <code>auto</code></strong>——当 overflow 为 visible 时解析为内容最小尺寸（约等于 min-content）。装着长标题、长 URL 的项目永远缩不下去，整行溢出。修复：给要被压缩的子项加 <code>min-width: 0</code>。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>Flex 的一切以&quot;轴&quot;为坐标系：<code>flex-direction</code> 指定<strong>主轴</strong>，与之垂直的是<strong>交叉轴</strong>。<code>justify-content</code> 永远管主轴，<code>align-items</code> 永远管交叉轴。把方向从 <code>row</code> 改成 <code>column</code> 后，两个属性的分工对象<strong>随之对调</strong>——这是&quot;垂直居中到底写 align 还是 justify&quot;困惑的根源。写样式前先默念一遍：&quot;主轴在哪？&quot;</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p><code>flex: 1</code> 展开是 <code>1 1 0%</code>——基准为 0，剩余空间完全均分，<strong>三列永远等宽</strong>；<code>flex: auto</code> 展开是 <code>1 1 auto</code>——先按内容占位再均分剩余，<strong>内容多者更宽</strong>。一个做等分栏，一个做内容驱动的工具栏。另外记住：按钮、图标这类不该被拉伸压缩的&quot;刚性元素&quot;显式声明 <code>flex: none</code>（即 <code>0 0 auto</code>）。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>justify 管主轴，align 管交叉轴；<code>flex-direction: column</code> 时两者对调。</li><li>要压缩的子项写 <code>min-width: 0</code>，省略号才能登场——Flex 第一大坑（column 方向同理是 <code>min-height: 0</code>）。</li><li>等分 <code>flex: 1</code>，按内容 <code>flex: auto</code>，刚性元素 <code>flex: none</code>；间距一律 <code>gap</code>，别再用 <code>:not(:last-child)</code> margin 技巧。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：三列内容分别是 &quot;1&quot;、&quot;标题很长很长很长&quot;、&quot;短&quot;，<code>.a { flex: 1 }</code> 和 <code>.b { flex: auto }</code> 的表现有何不同？</p><p><strong>答</strong>：<code>flex: 1</code>（basis 0）三项初始份额都是 0，剩余空间按 grow 完全均分，三列等宽；<code>flex: auto</code>（basis auto）初始份额等于各自内容宽度，剩余空间再均分，内容长的列更宽。本质区别在 <code>flex-basis</code> 的起点。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>主轴/交叉轴交互面板（direction、justify、align、wrap 实时切换）：<a href="./../../examples/css/03-flexbox/index-01-axis-alignment.html">examples/css/03-flexbox/</a></li><li>flex 三属性与 <code>flex:1</code> vs <code>flex:auto</code> 陷阱：<a href="./../../examples/css/03-flexbox/index-02-flex-grow-shrink-basis.html">index-02-flex-grow-shrink-basis.html</a></li><li>圣杯布局 + 粘性页脚：<a href="./../../examples/css/03-flexbox/index-03-holy-grail-sticky-footer.html">index-03-holy-grail-sticky-footer.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>一维排不下的二维对齐怎么办？第 4 话《Grid》：先分格，再落子，<code>1fr</code> 居然也有不听指挥的时候。</p>',22)])])}const u=o(c,[["render",d]]);export{f as __pageData,u as default};
